graphql.query:
query GetProductId($identifier: ProductIdentifierInput!) {
  product: productByIdentifier(identifier: $identifier) {
    id
    title
    handle
    category { id name }
  }
}

query ReadComprehensiveProduct($id: ID!) {
  product(id: $id) {
    id
    legacyResourceId
    title
    handle
    description
    descriptionHtml
    vendor
    productType
    status
    tags
    templateSuffix
    isGiftCard
    hasOnlyDefaultVariant
    hasOutOfStockVariants
    totalInventory
    tracksInventory
    createdAt
    updatedAt
    publishedAt
    onlineStoreUrl
    onlineStorePreviewUrl
    category { id name fullName }
    seo { title description }
    priceRangeV2 {
      minVariantPrice { amount currencyCode }
      maxVariantPrice { amount currencyCode }
    }
    options {
      id
      name
      position
      values
      optionValues { id name }
    }
    collections(first: 250) {
      nodes { id title handle updatedAt }
      pageInfo { hasNextPage endCursor }
    }
    media(first: 250) {
      nodes { ...ProductMediaFields }
      pageInfo { hasNextPage endCursor }
    }
    variants(first: 100) {
      nodes {
        id
        legacyResourceId
        title
        displayName
        sku
        barcode
        price
        compareAtPrice
        taxable
        inventoryPolicy
        inventoryQuantity
        position
        createdAt
        updatedAt
        selectedOptions { name value }
        image { id altText url width height }
        media(first: 20) { nodes { ...ProductMediaFields } pageInfo { hasNextPage endCursor } }
        metafields(first: 20) {
          nodes { id namespace key type value jsonValue createdAt updatedAt }
          pageInfo { hasNextPage endCursor }
        }
      }
      pageInfo { hasNextPage endCursor }
    }
    metafields(first: 250) {
      nodes {
        id
        namespace
        key
        type
        value
        jsonValue
        createdAt
        updatedAt
        definition { id name description access { storefront } }
      }
      pageInfo { hasNextPage endCursor }
    }
  }
}
fragment ProductMediaFields on Media {
  alt
  mediaContentType
  status
  preview { image { id altText url width height } status }
  ... on MediaImage { id image { id altText url width height } }
  ... on Video { id originalSource { format height mimeType url width } sources { format height mimeType url width } }
  ... on ExternalVideo { id host originUrl embedUrl }
  ... on Model3d { id originalSource { format mimeType url } sources { format mimeType url } }
}

mutation PatchProductAndMetafields($product: ProductUpdateInput!) {
  productUpdate(product: $product) {
    product {
      id
      title
      handle
      descriptionHtml
      vendor
      productType
      status
      tags
      templateSuffix
      seo { title description }
      category { id name fullName }
      metafields(first: 250) { nodes { id namespace key type value updatedAt } }
      updatedAt
    }
    userErrors { field message code }
  }
}

