mutation PatchProductVariants($productId: ID!, $variants: [ProductVariantsBulkInput!]!) {
  productVariantsBulkUpdate(productId: $productId, variants: $variants, allowPartialUpdates: false) {
    product { id title updatedAt }
    productVariants {
      id
      title
      sku
      barcode
      price
      compareAtPrice
      taxable
