}

mutation SetAllProductPageMetafields($editorial: [MetafieldsSetInput!]!, $teaRecord: [MetafieldsSetInput!]!) {
  editorial: metafieldsSet(metafields: $editorial) {
    metafields { id namespace key type value updatedAt }
    userErrors { field message code }
  }
  teaRecord: metafieldsSet(metafields: $teaRecord) {
    metafields { id namespace key type value updatedAt }
    userErrors { field message code }
  }
}

query VerifyProductMetafields($id: ID!) {
  product(id: $id) {
    id
    title
    handle
    category { id name }
    variants(first: 20) { nodes { id title sku selectedOptions { name value } } }
    metafields(first: 100, namespace: "custom") {
      nodes { id namespace key type value updatedAt definition { id name access { storefront } } }
    }
  }
}

mutation AssignProductCategory($product: ProductUpdateInput!) {
  productUpdate(product: $product) {
    product { id title category { id name } }
    userErrors { field message code }
  }
}
